action.command:
cd /tmp/logic-extract && for f in $(find io -name "*.class"); do
  node -e '
  const fs=require("fs");
  const data=fs.readFileSync(process.argv[1]);
  let out="";
  for(let i=0;i<data.length;i++){const c=data[i]; if(c>=32&&c<127) out+=String.fromCharCode(c); else out+="\n";}
  const hits=out.split("\n").filter(s=>/maven\.pkg|packages\.github|swcode.*github|gpr|githubPackages|setUrl|amazonaws|/releases/i.test(s));
  if(hits.length){console.log(process.argv[1].split("/").pop()+": "); hits.slice(0,15).forEach(h=>console.log("   ",h));}
  ' "$f";
done 2>&1 | head -50

